insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-as-192', 'chemistry-atomic-structure', 'chemistry', 'A particle''s position is uncertain by 0.1 Å. The minimum Δv for an electron (m ≈ 9.1 × 10⁻³¹ kg, h/4π ≈ 5.3 × 10⁻³⁵) is nearest', '["5.8 × 10⁵ m s⁻¹","5.8 × 10⁶ m s⁻¹","5.8 × 10⁷ m s⁻¹","5.8 × 10¹ m s⁻¹"]'::jsonb, 1, 'Δx = 10⁻¹¹ m, so Δp ≥ 5.3 × 10⁻²⁴ kg m s⁻¹ and Δv ≥ Δp/m ≈ 5.8 × 10⁶ m s⁻¹.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
